```typescript
/**
 * 固定容量的 LRU Cache，get 和 put 均摊 O(1)。
 *
 * 数据结构选择：
 * 1. Map<K, Node> —— 用于 O(1) 查找节点（key -> node 映射）
 * 2. 双向链表（Doubly Linked List）—— 用于 O(1) 移动/删除/插入节点，维护访问顺序
 *
 * 为什么不用普通 Map 或数组？
 * - 普通 Map 无法在 O(1) 内维护“最近最少使用”的顺序。
 * - 数组/链表单独使用无法在 O(1) 内按 key 查找。
 * - 双向链表 + Map 的组合是 LRU 的经典最优解：
 *   - Map 提供 O(1) 的 key 查找
 *   - 双向链表提供 O(1) 的头部插入、尾部删除、任意节点移动
 */

interface Node<K, V> {
  key: K;
  value: V;
  prev: Node<K, V> | null;
  next: Node<K, V> | null;
}

class LRUCache<K, V> {
  private capacity: number;
  private size: number;
  private map: Map<K, Node<K, V>>;
  // 哨兵节点：head 后面是最近使用的，tail 前面是最久未使用的
  private head: Node<K, V>;
  private tail: Node<K, V>;

  constructor(capacity: number) {
    if (capacity <= 0) {
      throw new Error("Capacity must be positive");
    }
    this.capacity = capacity;
    this.size = 0;
    this.map = new Map<K, Node<K, V>>();

    // 创建哨兵节点
    this.head = { key: undefined as unknown as K, value: undefined as unknown as V, prev: null, next: null };
    this.tail = { key: undefined as unknown as K, value: undefined as unknown as V, prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  /**
   * 获取 key 对应的值。如果存在，将该节点移到链表头部（标记为最近使用）。
   * 时间复杂度：O(1)
   */
  get(key: K): V | undefined {
    const node = this.map.get(key);
    if (!node) {
      return undefined;
    }
    // 将节点移到头部
    this.moveToHead(node);
    return node.value;
  }

  /**
   * 插入或更新 key-value。
   * - 如果 key 已存在，更新值并移到头部。
   * - 如果 key 不存在且容量未满，创建新节点插入头部。
   * - 如果 key 不存在且容量已满，删除尾部节点（最久未使用）后插入新节点。
   * 时间复杂度：O(1)
   */
  put(key: K, value: V): void {
    const existingNode = this.map.get(key);

    if (existingNode) {
      // 更新值
      existingNode.value = value;
      // 移到头部
      this.moveToHead(existingNode);
      return;
    }

    // 容量已满，删除最久未使用的节点（尾部前一个）
    if (this.size === this.capacity) {
      const lruNode = this.tail.prev!;
      this.removeNode(lruNode);
      this.map.delete(lruNode.key);
      this.size--;
    }

    // 创建新节点并插入头部
    const newNode: Node<K, V> = {
      key,
      value,
      prev: null,
      next: null,
    };
    this.map.set(key, newNode);
    this.insertAtHead(newNode);
    this.size++;
  }

  /**
   * 获取当前缓存大小
   */
  get size_(): number {
    return this.size;
  }

  /**
   * 获取缓存容量
   */
  get capacity_(): number {
    return this.capacity;
  }

  /**
   * 将节点从当前位置移除
   */
  private removeNode(node: Node<K, V>): void {
    const prev = node.prev!;
    const next = node.next!;
    prev.next = next;
    next.prev = prev;
    node.prev = null;
    node.next = null;
  }

  /**
   * 将节点插入到头部（head 之后）
   */
  private insertAtHead(node: Node<K, V>): void {
    const first = this.head.next!;
    this.head.next = node;
    node.prev = this.head;
    node.next = first;
    first.prev = node;
  }

  /**
   * 将节点移到头部：先移除，再插入头部
   */
  private moveToHead(node: Node<K, V>): void {
    this.removeNode(node);
    this.insertAtHead(node);
  }
}

// ==================== 最小使用示例 ====================

function main() {
  const cache = new LRUCache<string, number>(2);

  cache.put("a", 1);
  cache.put("b", 2);
  console.log(cache.get("a")); // 1  (a 变为最近使用)

  cache.put("c", 3); // 淘汰 "b"（最久未使用）
  console.log(cache.get("b")); // undefined (b 已被淘汰)
  console.log(cache.get("a")); // 1
  console.log(cache.get("c")); // 3

  cache.put("a", 10); // 更新 a 的值
  console.log(cache.get("a")); // 10

  cache.put("d", 4); // 淘汰 "c"（因为 a 刚被更新，c 是最久未使用的）
  console.log(cache.get("c")); // undefined
  console.log(cache.get("a")); // 10
  console.log(cache.get("d")); // 4
}

main();
